// Converts a standalone type!beat map folder (audio + lyrics.txt + timing.json) into a
// .osz importable by the typebeat-osu fork. The .osu's [Lyrics] payload is generated by
// typebeat.Game.Rulesets.TypeBeat.Beatmaps.LyricOsuFormat — the exact writer the decoder
// round-trip tests pin — so tool output and decoder input can never drift apart.
//
// Usage: dotnet run --project tools/TypeBeatOszConverter -- "<map folder>" "<output .osz>"
// Defaults (no args): the standalone Spectator folder -> artifacts/spectator.osz.

using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using typebeat.Game.Rulesets.TypeBeat.Beatmaps;

const string default_map_folder = @"C:\Users\Mingda\Documents\type!beat\maps\Friday Pilots Club - Spectator";
const string default_output = @"C:\Users\Mingda\Documents\typebeat-osu\artifacts\spectator.osz";

string mapFolder = args.Length > 0 ? args[0] : default_map_folder;
string outputPath = args.Length > 1 ? args[1] : default_output;

if (!Directory.Exists(mapFolder))
{
    Console.Error.WriteLine($"Map folder not found: {mapFolder}");
    return 1;
}

string timingPath = Path.Combine(mapFolder, "timing.json");

if (!File.Exists(timingPath))
{
    Console.Error.WriteLine($"timing.json not found in {mapFolder} (line-level-only maps are not supported by this tool yet).");
    return 1;
}

string? audioPath = Directory.EnumerateFiles(mapFolder)
                             .FirstOrDefault(f => new[] { ".mp3", ".ogg", ".wav" }.Contains(Path.GetExtension(f).ToLowerInvariant()));

if (audioPath == null)
{
    Console.Error.WriteLine($"No audio file (.mp3/.ogg/.wav) found in {mapFolder}");
    return 1;
}

string folderName = Path.GetFileName(mapFolder.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
int dash = folderName.IndexOf(" - ", StringComparison.Ordinal);
string artist = dash > 0 ? folderName[..dash].Trim() : "Unknown Artist";
string title = dash > 0 ? folderName[(dash + 3)..].Trim() : folderName;

string audioFilename = Path.GetFileName(audioPath);
string timingJson = File.ReadAllText(timingPath);

string osuText;

try
{
    osuText = LyricOsuFormat.GenerateOsu(artist, title, audioFilename, "typebeat-lyriclab", timingJson);
}
catch (ArgumentException e)
{
    Console.Error.WriteLine($"timing.json rejected: {e.Message}");
    return 1;
}

Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(outputPath))!);
File.Delete(outputPath);

using (var archive = ZipFile.Open(outputPath, ZipArchiveMode.Create))
{
    var osuEntry = archive.CreateEntry($"{sanitize(artist)} - {sanitize(title)} (typebeat-lyriclab) [typebeat].osu");
    using (var writer = new StreamWriter(osuEntry.Open()))
        writer.Write(osuText);

    archive.CreateEntryFromFile(audioPath, audioFilename);

    // Provenance: the original inputs travel inside the set (ignored by the game, kept for re-alignment).
    archive.CreateEntryFromFile(timingPath, "timing.json");

    string lyricsPath = Path.Combine(mapFolder, "lyrics.txt");
    if (File.Exists(lyricsPath))
        archive.CreateEntryFromFile(lyricsPath, "lyrics.txt");
}

Console.WriteLine($"Wrote {outputPath}");
Console.WriteLine($"  artist: {artist}");
Console.WriteLine($"  title:  {title}");
Console.WriteLine($"  audio:  {audioFilename}");
return 0;

static string sanitize(string name)
{
    foreach (char c in Path.GetInvalidFileNameChars())
        name = name.Replace(c, '_');
    return name;
}
